load_dotenv()
client = OpenAI()
MODEL = "gpt-5.5"   # use a model available to your account


# ---------------------------------------------------------
# PART 1: Your real functions
# ---------------------------------------------------------
def get_weather(city):
    """Still a stub, but now it differs per city."""
    print(f"   [your code] get_weather({city!r})")
    fake_data = {
        "mumbai": {"temp": 31, "condition": "light rain"},
        "delhi": {"temp": 38, "condition": "sunny"},
        "tokyo": {"temp": 22, "condition": "cloudy"},
    }
    return fake_data.get(city.lower(), {"error": f"No weather data for '{city}'"})


def get_time(timezone):
    """A REAL tool: reads the actual clock for any IANA timezone."""
    print(f"   [your code] get_time({timezone!r})")
    try:
        now = datetime.now(ZoneInfo(timezone))
        return {"timezone": timezone, "time": now.strftime("%Y-%m-%d %H:%M:%S")}
    except Exception:
        return {"error": f"Unknown timezone '{timezone}'. Use names like 'Asia/Kolkata'."}


# Registry: tool name -> real function
AVAILABLE_FUNCTIONS = {
    "get_weather": get_weather,
    "get_time": get_time,
}


# ---------------------------------------------------------
# PART 2: The "menu" describing both tools to the model
# ---------------------------------------------------------
tools = [
    {
        "type": "function",
        "function": {
            "name": "get_weather",
            "description": "Get current weather for a city. Use for questions about "
                           "rain, temperature or conditions. Not for time questions.",
            "parameters": {
                "type": "object",
                "properties": {
                    "city": {"type": "string", "description": "City name, e.g. 'Mumbai'"}
                },
                "required": ["city"],
            },
        },
    },
    {
        "type": "function",
        "function": {
            "name": "get_time",
            "description": "Get the current local date and time for a timezone. "
                           "Use when the user asks what time or date it is somewhere.",
            "parameters": {
                "type": "object",
                "properties": {
                    "timezone": {
                        "type": "string",
                        "description": "IANA timezone name, e.g. 'Asia/Kolkata', 'Asia/Tokyo'",
                    }
                },
                "required": ["timezone"],
            },
        },
    },
]


# ---------------------------------------------------------
# PART 3: The loop (handles one OR many tool rounds)
# ---------------------------------------------------------
def ask(question, max_rounds=5):
    print(f"\n=== USER: {question}")
    messages = [{"role": "user", "content": question}]

    for _ in range(max_rounds):                       # cap, so it can't loop forever
        response = client.chat.completions.create(
            model=MODEL, messages=messages, tools=tools
        )
        msg = response.choices[0].message

        if not msg.tool_calls:                        # no tool requested -> final answer
            print(f"=== MODEL: {msg.content}")
            return msg.content

        messages.append(msg)                          # keep the model's request in history

        for call in msg.tool_calls:                   # may be 1 or several (parallel)
            name = call.function.name
            args = json.loads(call.function.arguments)

            func = AVAILABLE_FUNCTIONS.get(name)
            result = func(**args) if func else {"error": f"Unknown tool '{name}'"}

            messages.append({
                "role": "tool",
                "tool_call_id": call.id,              # must match the request
                "content": json.dumps(result),
            })

    print("=== Stopped: too many rounds")


