    {"role": "system", "content": "You are a helpful assistant. Use toolswhen needed."},
    {"role": "user", "content": "Is it warmer in Paris or Hyderabad?"},
]

# --- Limits ---
MAX_STEPS = 6
MAX_TOTAL_TOKENS = 20_000
MAX_SECONDS = 60

start_time = time.time()
total_tokens = 0
seen_calls = set()          # for repeat detection
stop_reason = None

for step in range(1, MAX_STEPS + 1):
    # Check time and token budgets before spending more
    if time.time() - start_time > MAX_SECONDS:
        stop_reason = "time limit reached"
        break
    if total_tokens > MAX_TOTAL_TOKENS:
        stop_reason = "token budget reached"
        break

    response = client.chat.completions.create(
        model="gpt-4o-mini",  # check current model names in OpenAI's docs        messages=messages,
        tools=tools,
    )
    total_tokens += response.usage.total_tokens
    message = response.choices[0].message
    messages.append(message)

