    if not message.tool_calls:
        print("Final answer:", message.content)
        stop_reason = "finished"
        break

    for call in message.tool_calls:
        args = json.loads(call.function.arguments)
        signature = (call.function.name, json.dumps(args, sort_keys=True))

        # Repeat detection: same tool, same arguments as before
        if signature in seen_calls:
            result = "You already made this exact call. Use the earlier
result or try something different."
        else:
            seen_calls.add(signature)
            try:
                result = available_functions[call.function.name](**args)
            except Exception as e:
                result = f"Error running tool: {e}"

        messages.append({"role": "tool", "tool_call_id": call.id,
"content": result})
