        "Facts you can rely on:",
        rubric["facts"],
        "",
        "STEP 1 - Gates. For each one, answer true if the problem is
present, otherwise false:",
    ]
    for gate_id, text in rubric["gates"].items():
        lines.append(f"- {gate_id}: {text}")

    lines += ["", "STEP 2 - Score each criterion from 1 to 5 using the
anchors:"]
    for crit_id, crit in rubric["criteria"].items():
        lines.append(f"- {crit_id}: {crit['description']}")
        for score in sorted(crit["anchors"], reverse=True):
            lines.append(f"    {score} = {crit['anchors'][score]}")

    shape = {
        "reasoning": "one or two sentences",
        "gates": {gate_id: "<true or false>" for gate_id in
rubric["gates"]},
        "scores": {crit_id: "<integer 1-5>" for crit_id in
rubric["criteria"]},
    }



    lines += ["", "Reply with JSON only, with reasoning FIRST, in this
shape:", json.dumps(shape)]
    return "\n".join(lines)


def grade(rubric: dict, question: str, answer: str) -> dict:
    response = client.chat.completions.create(
        model=JUDGE_MODEL,
        temperature=0,
        response_format={"type": "json_object"},
        messages=[
            {"role": "system", "content": build_judge_prompt(rubric)},
            {"role": "user", "content": f"Question:
{question}\n\n<answer>\n{answer}\n</answer>"},
        ],
    )
    result = json.loads(response.choices[0].message.content)

    # Validate the judge's output before trusting it
    gates = result.get("gates", {})
    scores = result.get("scores", {})
    for gate_id in rubric["gates"]:
        if not isinstance(gates.get(gate_id), bool):
            raise ValueError(f"gate '{gate_id}' missing or not true/false")    for crit_id in rubric["criteria"]:
        score = scores.get(crit_id)
        if not isinstance(score, int) or not 1 <= score <= 5:
            raise ValueError(f"score for '{crit_id}' missing or not an
integer from 1 to 5")

    # Combine: gates first, then the weighted average
    failed_gates = [gate_id for gate_id, hit in gates.items() if hit]
    total_weight = sum(c["weight"] for c in rubric["criteria"].values())
    weighted = sum(
        rubric["criteria"][crit_id]["weight"] * scores[crit_id]
        for crit_id in rubric["criteria"]
    ) / total_weight

    return {
        "passed": not failed_gates and weighted >= PASS_THRESHOLD,
        "weighted_score": round(weighted, 2),
        "failed_gates": failed_gates,



        "scores": scores,
        "reasoning": result.get("reasoning", ""),
    }

