import re

DOCS = {
    "doc-returns": "Items can be returned within 30 days of purchase. Refunds go to the originalpayment method.",
    "doc-hours": "Support is open 9am to 5pm, Monday to Friday.",
    "doc-shipping": "Standard shipping takes 3 to 5 business days. Express shipping takes 1 to 2business days.",
    "doc-warranty": "All electronics include a 1 year warranty against manufacturing defects.",    "doc-gift": "Gift cards never expire and can be used on any order.",
}

STOPWORDS = {"how", "do", "does", "i", "to", "a", "an", "the", "is", "can", "my", "of",             "on", "or", "be", "in", "and", "have", "get", "when", "you", "are", "it", "for","any"}


def normalise(word: str) -> str:
    """Very crude stemming so 'returned' and 'return' match."""
    if word.endswith("ed") and len(word) > 4:
        return word[:-2]
    if word.endswith("s") and len(word) > 3:
        return word[:-1]
    return word


def tokens(text: str) -> set:
    words = re.findall(r"[a-z0-9]+", text.lower())
    return {normalise(w) for w in words if w not in STOPWORDS}


def retrieve(question: str, k: int) -> list:
    """A toy retriever: rank documents by how many words they share with the question."""    question_words = tokens(question)
    scores = {doc_id: len(question_words & tokens(text)) for doc_id, text in DOCS.items()}



    ranked = sorted(scores, key=lambda doc_id: -scores[doc_id])
    return [doc_id for doc_id in ranked if scores[doc_id] > 0][:k]


# The labelled test set: each question lists the documents that SHOULD be retrieved
test_cases = [
    {"question": "How many days do I have to return an item?", "gold_ids": ["doc-returns"]},    {"question": "When is support open?", "gold_ids": ["doc-hours"]},
    {"question": "How long does express shipping take?", "gold_ids": ["doc-shipping"]},    {"question": "Can I get my money back?", "gold_ids": ["doc-returns"]},
    {"question": "Do electronics have a warranty?", "gold_ids": ["doc-warranty"]},
    {"question": "How many days do I have to return an item, and is support open on Friday?",     "gold_ids": ["doc-returns", "doc-hours"]},
    {"question": "Do you sell gift wrapping?", "gold_ids": []},   # unanswerable
]


def evaluate_retrieval(cases: list, k: int) -> dict:
    hits = recall_total = precision_total = reciprocal_rank_total = 0.0
    counted = 0
    for case in cases:
        gold = set(case["gold_ids"])
        if not gold:
            continue   # unanswerable questions are checked at the answer stage instead        retrieved = retrieve(case["question"], k)
        found = [doc_id for doc_id in retrieved if doc_id in gold]

        counted += 1
        hits += 1 if found else 0
        recall_total += len(found) / len(gold)
        precision_total += len(found) / len(retrieved) if retrieved else 0
        for rank, doc_id in enumerate(retrieved, start=1):
            if doc_id in gold:
                reciprocal_rank_total += 1 / rank
                break

    return {
        "hit_rate": hits / counted,
        "recall": recall_total / counted,
        "precision": precision_total / counted,
        "mrr": reciprocal_rank_total / counted,
    }





for k in (1, 3):
    scores = evaluate_retrieval(test_cases, k)
    print(f"k={k}: " + ", ".join(f"{name}={value:.2f}" for name, value in scores.items()))

