        print(f"  {case['question']!r} -> retrieved {retrieved}, wanted {sorted(gold)}")

import json
import re
import time
import uuid
from datetime import datetime, timezone
from openai import OpenAI

client = OpenAI()
MODEL = "gpt-4o-mini"  # check current model names in OpenAI's docs
LOG_FILE = "agent_log.jsonl"
MAX_STEPS = 5

# ---------- Logging helpers ----------
EMAIL = re.compile(r"[\w.+-]+@[\w-]+\.[\w.]+")
PHONE = re.compile(r"\+?\d[\d\s().-]{7,}\d")


def redact(text):
    """Mask obvious personal data. This is a basic safety net, not a
guarantee."""
    if not isinstance(text, str):
        return text
    text = EMAIL.sub("[EMAIL]", text)
    return PHONE.sub("[PHONE]", text)


def redact_messages(messages: list) -> list:
    return [{**m, "content": redact(m.get("content"))} for m in messages]


def now() -> str:
    return datetime.now(timezone.utc).isoformat()


def write_log(record: dict) -> None:
    """Append one JSON line. Logging must never break the app."""
    try:
        with open(LOG_FILE, "a", encoding="utf-8") as f:
            f.write(json.dumps(record, ensure_ascii=False, default=str) +"\n")
    except OSError as e:
        print(f"(warning: could not write log: {e})")





# ---------- The agent's tool ----------
def get_weather(city: str) -> str:
    fake_data = {"Paris": "18°C, cloudy", "Hyderabad": "31°C, sunny"}
    return fake_data.get(city, "No data for that city")


tools = [{
    "type": "function",
    "function": {
        "name": "get_weather",
        "description": "Get the current weather for a city",
        "parameters": {
            "type": "object",
            "properties": {"city": {"type": "string"}},
            "required": ["city"],
        },
    },
}]
available_functions = {"get_weather": get_weather}


# ---------- Logged model call ----------
def logged_chat(trace_id: str, step: int, messages: list):
    started = time.time()
    record = {
        "timestamp": now(),
        "trace_id": trace_id,
        "step": step,
        "event": "llm_call",
        "model_requested": MODEL,
        "prompt_version": "v1",
        "messages": redact_messages(messages),
    }
    try:
        response = client.chat.completions.create(model=MODEL,
messages=messages, tools=tools)
        choice = response.choices[0]
        record.update({
            "status": "ok",
            "model_returned": response.model,



            "finish_reason": choice.finish_reason,
            "response": redact(choice.message.content),
            "requested_tools": [
                {"name": c.function.name, "arguments":
c.function.arguments}
                for c in (choice.message.tool_calls or [])
            ],
            "prompt_tokens": response.usage.prompt_tokens,
            "completion_tokens": response.usage.completion_tokens,
        })
        return response
    except Exception as e:
        record.update({"status": "error", "error": f"{type(e).__name__}:
{e}"})
        raise
    finally:
        record["seconds"] = round(time.time() - started, 3)
        write_log(record)


# ---------- The agent loop ----------
def run_agent(question: str):
    trace_id = str(uuid.uuid4())
    messages = [
        {"role": "system", "content": "You are a helpful assistant. Use
tools when needed."},
        {"role": "user", "content": question},
    ]
    write_log({"timestamp": now(), "trace_id": trace_id, "event":
"run_start",
               "question": redact(question)})

    final_answer = None
    for step in range(1, MAX_STEPS + 1):
        response = logged_chat(trace_id, step, messages)
        message = response.choices[0].message

        # Store the assistant turn as a plain dict, so it can be logged andre-sent
        assistant = {"role": "assistant", "content": message.content}
        if message.tool_calls:
            assistant["tool_calls"] = [



                {"id": c.id, "type": "function",
                 "function": {"name": c.function.name, "arguments":
c.function.arguments}}
                for c in message.tool_calls
            ]
        messages.append(assistant)

        if not message.tool_calls:
            final_answer = message.content
            break

        for call in message.tool_calls:
            started = time.time()
            error = None
            try:
                args = json.loads(call.function.arguments)
                result = available_functions[call.function.name](**args)
            except Exception as e:
                error = f"{type(e).__name__}: {e}"
                result = f"Error running tool: {e}"
            write_log({
                "timestamp": now(), "trace_id": trace_id, "step": step,
"event": "tool_call",
                "name": call.function.name, "arguments":
call.function.arguments,
                "result": redact(result), "error": error,
                "seconds": round(time.time() - started, 3),
            })
            messages.append({"role": "tool", "tool_call_id": call.id,
"content": result})

    write_log({"timestamp": now(), "trace_id": trace_id, "event":
"run_end",
               "stop_reason": "finished" if final_answer else "step limitreached"})
    return trace_id, final_answer









