MANY_STEPS = 4         # Flag runs with this many model calls or more

# 1. Load and group events by trace_id
runs = {}
with open(LOG_FILE, encoding="utf-8") as f:
    for line in f:
        if line.strip():
            record = json.loads(line)
            trace_id = record["trace_id"]

            if trace_id not in runs:
                runs[trace_id] = []
            runs[trace_id].append(record)

# 2. Analyze each run
for trace_id, events in runs.items():
    llm_calls = []
    tool_calls = []
    errors = []
    end_event = {}




    for e in events:
        event_type = e.get("event")
        if event_type == "llm_call":
            llm_calls.append(e)
        elif event_type == "tool_call":
            tool_calls.append(e)
        elif event_type == "run_end":
            end_event = e

        if e.get("status") == "error" or e.get("error"):
            errors.append(e)

    # Calculate total tokens
    tokens = 0
    for e in llm_calls:
        tokens += e.get("prompt_tokens", 0) + e.get("completion_tokens", 0)

    # Calculate total time in seconds
    seconds = 0
    for e in events:
        seconds += e.get("seconds", 0)

    # Check for warning flags
    flags = []
    if len(errors) > 0:
        flags.append("ERRORS")
    if seconds > SLOW_SECONDS:
        flags.append("SLOW")
    if len(llm_calls) >= MANY_STEPS:
        flags.append("MANY STEPS")
    if end_event.get("stop_reason") != "finished":
        flags.append("DID NOT FINISH")

    # Check if any LLM call was cut off due to token limits
    cut_off = False
    for e in llm_calls:
        if e.get("finish_reason") == "length":
            cut_off = True
            break
    if cut_off:
        flags.append("CUT OFF AT TOKEN LIMIT")




    flag_text = " ".join(flags)
    if flag_text == "":
        flag_text = "ok"

    print(
        f"{trace_id[:8]}  model calls: {len(llm_calls)}  tool calls:
{len(tool_calls)}  "
        f"tokens: {tokens}  time: {seconds:.1f}s  {flag_text}"
    )

# 3. Find the most expensive run by token count
worst_id = None
max_tokens = -1

for trace_id, events in runs.items():
    total_tokens = 0
    for e in events:
        total_tokens += e.get("prompt_tokens", 0) +
e.get("completion_tokens", 0)

    if total_tokens > max_tokens:
